// ====================== TRAME UART EN DIRECT =====================

public String octetHex(int valeur) {
  return hex(valeur & 0xFF, 2);
}

public String octetBinaire(int valeur) {
  return binary(valeur & 0xFF, 8);
}

public String trameTexte(int[] octets) {
  String resultat = "";
  for (int i = 0; i < octets.length; i++) {
    if (i > 0) resultat += " ";
    resultat += octetHex(octets[i]);
  }
  return resultat;
}

public boolean surRectangle(float x, float y, float w, float h) {
  float mx = positionSourisX();
  float my = positionSourisY();
  return mx >= x && mx < x + w && my >= y && my < y + h;
}

